@metered
async def note_friction(severity: str, expected: str, happened: str) -> dict:
    ctx = current_run.get()
    page = await _active_page()
    friction = {
        "severity": severity,
        "expected": expected,
        "happened": happened,
        "url": await page.url(),
    }
